class Acid:
    def __init__(self, name, strength):
        self.name = name
        self.strength = strength  # 'strong' or 'weak'

    def dissociate(self):
        if self.strength == 'strong':
            return f"{self.name} fully dissociates into H⁺ and anions."
        else:
            return f"{self.name} partially dissociates into H⁺ and anions."

# Example usage
hcl = Acid("Hydrochloric Acid", "strong")
acetic_acid = Acid("Acetic Acid", "weak")

print(hcl.dissociate())
print(acetic_acid.dissociate())
